<script setup>
import {computed,ref} from 'vue'
import {useLearning} from '../useLearning.js'
import CourseOutlineDialog from './CourseOutlineDialog.vue'
import {artwork} from '../assets.js'
const emit=defineEmits(['new-goal'])
const {state,openCourse}=useLearning()
const category=ref('全部'),sort=ref('default'),outline=ref(null)
const tags=computed(()=>['全部',...new Set((state.boot?.courses||[]).map(c=>c.tag))])
const courses=computed(()=>{const rows=(state.boot?.courses||[]).filter(c=>(category.value==='全部'||c.tag===category.value)&&[c.title,c.description,c.tag].join(' ').toLowerCase().includes(state.query.trim().toLowerCase()));return [...rows].sort((a,b)=>sort.value==='time'?a.minutes-b.minutes:sort.value==='title'?a.title.localeCompare(b.title,'zh-CN'):0)})
const prompts=[{title:'科学与生活',description:'从身边的现象，提出可观察的问题。',image:'shelf-science',goal:'我想围绕一个生活现象，结合科学知识设计可以观察和解释的小实验'},{title:'社会与现实',description:'梳理不同视角，检查证据与判断。',image:'shelf-society',goal:'我想结合历史、社会和数据，理解一个现实问题并核查不同观点'},{title:'生活与成长',description:'用新的方法，理解自己的日常。',image:'shelf-life',goal:'我想结合阅读、思维方法与日常生活，形成一个可以持续练习的小目标'}]
</script>
<template><div class="course-gallery-live"><div class="course-gallery-toolbar"><div class="studio-pills"><button v-for="tag in tags" :key="tag" :class="{active:category===tag}" @click="category=tag">{{ tag }}</button></div><label>排序<select v-model="sort"><option value="default">默认顺序</option><option value="time">时长较短</option><option value="title">按标题</option></select></label></div><div class="course-gallery-layout"><section class="humanities-feature"><img src="/assets/split-elements/elements/humanities-feature.compact.webp" alt="人文探索插画"><div><span class="course-tag lavender">自选跨学科主题</span><h2>重新理解，<br>我们身处的世界。</h2><p>从一个真实问题出发，把历史、科学和艺术放在一起思考。</p><button class="primary-button" @click="emit('new-goal','我想结合人文、历史和科学，理解一个现实世界的问题')">创建我的探索目标</button></div></section><div class="course-gallery-cards"><article v-for="course in courses" :key="course.id"><img :src="artwork[course.id]" :alt="course.tag+'课程配图'"><div><span class="course-tag" :class="course.tint">{{ course.tag }}</span><h2>{{ course.title }}</h2><p>{{ course.description }}</p><small>{{ course.lesson_count }} 个学习单元 · 练习路线约 {{ course.minutes }} 分钟</small><p class="course-reference-caption">依据：{{ course.reference?.title }}</p><div class="course-path-actions"><button class="secondary-button" @click="outline=course.id">目录与课程依据</button><button class="secondary-button" @click="openCourse(course.id)">{{ state.boot?.sessions.some(s=>s.course_id===course.id)?'继续我的学习':'进入课程' }}</button><a v-if="course.id==='programming'" class="primary-button" href="/app?view=pbl">项目学习</a></div></div></article><div v-if="!courses.length" class="studio-empty-soft"><h3>没有匹配的课程</h3><p>可以换一个关键词，或创建自己的目标。</p><button class="secondary-button" @click="emit('new-goal',state.query)">用这个问题开始</button></div></div></div><section class="course-inspiration-strip"><h2>已有课程之外，也可以开始。</h2><p>以下是创建目标的方向，不是已经发布的课程。</p><div><button v-for="prompt in prompts" :key="prompt.title" @click="emit('new-goal',prompt.goal)"><img :src="'/assets/split-elements/scenes/'+prompt.image+'.png'" alt=""><span><strong>{{ prompt.title }}</strong><small>{{ prompt.description }}</small></span></button></div></section><CourseOutlineDialog v-if="outline" :course-id="outline" @close="outline=null"/></div></template>
